const PAGE="<!doctype html>\n<html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1, user-scalable=no\"><meta name=\"theme-color\" content=\"#84c7f7\"><title>POT BREAKER RE · CBZP</title>\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@700;800;900;1000&family=Gowun+Dodum&display=swap');\n:root{--navy:#303d67;--royal:#5578bd;--cream:#fff9ee;--sky:#93d0fa;--coral:#f8a76d;--gold:#ffd47e;--shadow:#3b466e54;font-family:'Nunito','Gowun Dodum','Malgun Gothic',system-ui,sans-serif}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#8dc6f4;color:var(--navy)}button{font:inherit;cursor:pointer;touch-action:manipulation}button:focus-visible{outline:3px solid #ffbe6d;outline-offset:3px}.viewport{height:100dvh;width:100vw;display:grid;place-items:center;background:radial-gradient(circle at 50% 0%,#dff8ff 0,#a5d9fc 45%,#70b8ee 100%)}\n.stage{aspect-ratio:16/9;width:min(100vw,177.778dvh);height:min(100dvh,56.25vw);position:relative;overflow:hidden;isolation:isolate;background:#f6eedf;box-shadow:0 2vh 7vh #2b467669}.hidden{display:none!important}.screen{position:absolute;inset:0;z-index:2;overflow:hidden}.menu{background:linear-gradient(115deg,#e7f8ff 0%,#b0dffc 64%,#98cafa);display:flex;align-items:center;padding:4.5%;gap:4%}.menu::before{content:\"\";position:absolute;inset:-7%;background:url('data:image/webp;base64,') center/cover;filter:blur(13px) saturate(.8);opacity:.25}.menu::after{content:\"\";pointer-events:none;position:absolute;inset:0;background:linear-gradient(90deg,#fffefaec 0%,#fffefa85 51%,transparent 90%)}.menu-left{position:relative;z-index:1;width:54%;filter:drop-shadow(0 5px 14px #fff5)}.eyebrow{font-size:clamp(11px,1.15vw,17px);font-weight:900;letter-spacing:.22em;color:#6482b5}.logo{margin:12px 0 5px;font-family:'Nunito',system-ui,sans-serif;font-size:clamp(44px,7.6vw,117px);line-height:.85;font-weight:1000;letter-spacing:-.075em;color:var(--navy);paint-order:stroke fill;text-shadow:-4px -4px white,4px -4px white,-4px 4px white,4px 4px white,0 10px #4561913e}.logo .pot{color:#f29c56}.logo .re{color:#5389dc;text-shadow:0 0 0 white}.sticker{display:inline-flex;align-items:center;gap:8px;margin:13px 0 8px;background:#fff4d6;border-radius:30px;padding:8px 17px;font-size:clamp(12px,1.35vw,19px);font-weight:1000;box-shadow:0 3px 0 #e2b66f79;transform:rotate(-2deg)}.menu-desc{font-size:clamp(13px,1.6vw,24px);font-weight:900;line-height:1.48;margin:16px 0 20px}.cta{border:3px solid #fff;border-radius:100px;color:#fff;background:linear-gradient(145deg,#648ddc,#446ab6);box-shadow:0 6px 0 #38528499,0 12px 23px #3b57914d;padding:13px 28px;font-weight:1000;font-size:clamp(13px,1.5vw,22px);white-space:nowrap;transition:transform .1s ease}.cta:active{transform:translateY(4px);box-shadow:0 2px 0 #38528499}.cta.secondary{color:var(--navy);background:#fffdf9;border:3px solid #bfdbf6;box-shadow:0 5px 0 #9ab5d0}.meta{font-size:clamp(10px,.9vw,14px);font-weight:900;color:#617394;margin:18px 0 0}.menu-characters{position:absolute;z-index:1;right:6%;bottom:8%;width:38%;height:75%;display:flex;align-items:end;justify-content:center}.character{object-fit:contain;filter:drop-shadow(0 15px 4px #3b46612b)}.menu-characters .cat{width:55%;z-index:2;transform:translate(17%,-2%) rotate(-8deg)}.menu-characters .croc{width:72%;z-index:1;transform:translate(-8%,3%) rotate(5deg)}.menu-characters .spark{position:absolute;font-size:clamp(35px,5vw,80px);color:#ffd17e;top:4%;right:15%;text-shadow:0 0 10px white}.logo-mark{position:absolute;top:5%;right:5%;z-index:1;font-size:clamp(15px,1.8vw,24px);font-weight:1000;color:#3e5c99;background:#ffffffc9;padding:9px 17px;border:2px solid white;border-radius:22px}\n.intro{background:linear-gradient(115deg,#f1faff,#a7d5f9);display:grid;grid-template-columns:minmax(0,72%) 1fr;gap:2%;align-items:center;padding:1.7% 2.3%}.comic-cover{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 8px 6px #4f71a139);border-radius:17px}.intro-side{display:flex;flex-direction:column;align-items:start;gap:min(2vw,24px);min-width:0}.intro-side h2{font-size:clamp(20px,3.15vw,45px);font-weight:1000;line-height:1.16;margin:0}.intro-side p{font-size:clamp(11px,1.25vw,19px);font-weight:800;line-height:1.5;margin:0}.intro-side small{font-size:clamp(10px,.95vw,15px);line-height:1.45;color:#617292}.paper{border:3px solid #fff;background:#fffcf5c9;border-radius:24px;padding:min(1.5vw,20px);box-shadow:0 6px 17px #456f9540}\n.play{background:#f3eada}#board{position:absolute;width:100%;height:100%;inset:0;display:block;touch-action:none}.play::before{content:\"\";position:absolute;z-index:1;pointer-events:none;inset:0;background:linear-gradient(#d5ebff58,transparent 19%,transparent 78%,#e5bd8050)}.hudbar{position:absolute;z-index:4;top:2.3%;left:2.4%;right:2.4%;display:flex;justify-content:space-between;align-items:start;gap:1.2%;pointer-events:none}.hud-panel{display:flex;align-items:center;gap:clamp(3px,.7vw,12px);border:2px solid #fff;padding:clamp(4px,.55vw,10px) clamp(6px,.9vw,15px);border-radius:19px;background:#fffdf1e8;box-shadow:0 5px 0 #536d9652,0 9px 20px #35456527;backdrop-filter:blur(7px);font-weight:1000;font-size:clamp(10px,1.2vw,18px);white-space:nowrap}.hud-panel.cat{border-color:#c6e5fb}.hud-panel.croc{border-color:#ffe0bb}.hud-img{height:clamp(25px,3.8vw,57px);width:clamp(25px,3.8vw,57px);object-fit:contain}.mini-pot{width:clamp(21px,2.2vw,36px);vertical-align:middle}.hud-name{font-size:clamp(9px,1vw,14px);color:#697b9c;display:block;line-height:1.1}.hud-value{font-size:clamp(12px,1.4vw,22px);line-height:1.25}.hud-status{align-items:center;gap:3px}.hud-center{display:flex;flex-direction:column;align-items:center;gap:4px;font-weight:1000;font-size:clamp(10px,1.15vw,17px);color:#394b76;text-shadow:0 2px white}.hud-center>div{border:2px solid #fff;background:#ffffffc9;padding:3px 13px;border-radius:12px}.hud-pause{pointer-events:auto;align-self:start;border:2px solid white;background:#fffdf1eb;color:#4a6399;border-radius:50%;height:clamp(27px,3vw,48px);aspect-ratio:1;font-size:clamp(12px,1.3vw,20px);box-shadow:0 4px 0 #6b80a855}\n.touch-layer{position:absolute;inset:0;z-index:3;pointer-events:none}.joystick{position:absolute;left:3.6%;bottom:7%;width:clamp(102px,13vw,192px);aspect-ratio:1;border-radius:100%;border:3px solid #f8feffcb;background:radial-gradient(circle,#ffffff4f,#cedcf174);box-shadow:inset 0 1px 15px #ffffff7a,0 6px 12px #324c6b44;pointer-events:auto;touch-action:none}.joystick:before{content:'↑';font-size:17px;position:absolute;top:8px;left:50%;transform:translateX(-50%);color:#617cb0aa;font-weight:900}.knob{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:52%;aspect-ratio:1;border-radius:100%;background:linear-gradient(130deg,#fffffff2,#eef7ffdf);box-shadow:0 4px 11px #4458766b,inset 0 2px 6px #fff;border:3px solid #fff}.actions{position:absolute;right:3.5%;bottom:7%;display:flex;gap:clamp(9px,1.4vw,20px);align-items:end;pointer-events:auto}.action{display:flex;flex-direction:column;align-items:center;justify-content:center;width:clamp(75px,9vw,132px);aspect-ratio:1;border-radius:100%;border:4px solid #fffcf5;background:linear-gradient(160deg,#fff4c6,#e9c986);color:#394b73;box-shadow:0 6px 0 #68819f8a,0 7px 12px #3c507854;font-weight:1000;font-size:clamp(9px,1vw,16px)}.action .symbol{font-size:clamp(20px,3vw,46px);line-height:1.05}.action.jump{width:clamp(65px,7.5vw,112px);background:linear-gradient(155deg,#e6f3ff,#b2cff4)}.action.fire{background:linear-gradient(145deg,#77b7fe,#457cdb);color:#fff;font-size:clamp(11px,1.1vw,18px)}.action:disabled{opacity:.55;filter:grayscale(.45)}.action:active{transform:translateY(4px);box-shadow:0 2px 0 #68819f8a}.status-pill{position:absolute;top:17%;left:50%;transform:translateX(-50%);border:3px solid #fff;background:#fffaebf0;color:#75533c;box-shadow:0 4px 18px #584c5760;border-radius:99px;padding:5px 16px;font-weight:1000;font-size:clamp(10px,1.1vw,17px);pointer-events:none;z-index:4;white-space:nowrap}.bell{position:absolute;top:17%;left:50%;transform:translateX(-50%);font-weight:1000;color:#b47535;text-shadow:0 2px white;background:#fff6e1ce;padding:3px 16px;border-radius:99px;font-size:clamp(11px,1.25vw,20px);z-index:4;pointer-events:none}.legend{position:absolute;left:50%;bottom:2%;transform:translateX(-50%);z-index:3;font-size:clamp(8px,.9vw,13px);font-weight:1000;color:#5b6c8b;padding:4px 12px;border:1px solid #fff9;border-radius:99px;background:#fffbd2ba;white-space:nowrap;pointer-events:none}.end{background:#a2d9fd}.ending-art{width:100%;height:100%;object-fit:cover}.end::after{content:\"\";position:absolute;inset:0;background:linear-gradient(90deg,#151a398a 0%,transparent 70%)}.end-panel{position:absolute;z-index:2;left:4%;top:14%;color:white;text-shadow:0 3px 8px #1f2a50aa;max-width:53%}.end-panel .tag{font-size:clamp(14px,1.9vw,28px);color:#384c76;background:#fff4d3;padding:6px 18px;border-radius:99px;display:inline-block;text-shadow:none;font-weight:1000}.end-panel h2{font-size:clamp(31px,5vw,76px);line-height:1.1;margin:18px 0;font-weight:1000;white-space:nowrap}.end-panel p{font-size:clamp(12px,1.6vw,23px);font-weight:900;line-height:1.5}.end-btns{display:flex;gap:10px;margin-top:25px}.loader{position:absolute;z-index:11;inset:0;display:grid;place-items:center;background:#e2f6ffec;backdrop-filter:blur(9px)}.loader-card{width:min(500px,85%);background:#fffdf2;border:4px solid white;border-radius:28px;padding:26px;box-shadow:0 10px 30px #3b64934d;text-align:center}.loading-spin{width:46px;height:46px;margin:auto auto 17px;border:6px solid #cbe1f9;border-top-color:#4a7cbd;border-radius:100%;animation:rot .8s linear infinite}@keyframes rot{to{transform:rotate(360deg)}}.loader-card strong{display:block;font-size:clamp(17px,2.2vw,31px)}.loader-card p{font-weight:700;font-size:clamp(11px,1.2vw,17px)}.loader-card button{margin-top:8px}.pause-overlay{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:#243254b0;backdrop-filter:blur(5px)}.pause-card{background:#fffcf0;border:4px solid white;box-shadow:0 14px 38px #1724497a;border-radius:24px;padding:30px;display:flex;flex-direction:column;align-items:center;gap:18px}.pause-card h2{font-size:clamp(20px,3vw,43px);margin:0}\n.rotate{position:absolute;z-index:20;inset:0;display:none;place-items:center;background:#e5f5ff;text-align:center;font-weight:1000;font-size:20px;padding:22px}@media (orientation:portrait) and (max-width:800px){.rotate{display:grid}}@media (max-height:500px){.menu-desc{margin:8px 0 12px}.sticker{margin:5px 0}.meta{margin-top:7px}.intro-side{gap:9px}}@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}\n</style></head><body>\n<div class=\"viewport\"><main class=\"stage\" id=\"stage\">\n<section class=\"screen menu\" id=\"title\"><div class=\"logo-mark\">☁︎ CBZP <span style=\"color:#f2bd62\">✦</span></div><div class=\"menu-left\"><div class=\"eyebrow\">CLOUD BEAR ZOO PARK · OFFICE CHASE</div><h1 class=\"logo\"><span class=\"pot\">POT</span><br>BREAKER<span class=\"re\"> RE</span></h1><div class=\"sticker\">🪴 CBZP 인턴 기묘의 생존(?) 프로젝트</div><p class=\"menu-desc\">오늘도 출근했습니다.<br>그리고 누군가 화분을 던졌습니다.</p><button class=\"cta\" id=\"openIntro\">▶ &nbsp; 첫 출근 시작하기</button><div class=\"meta\">SINGLE PLAYER &nbsp; • &nbsp; 스마트폰 가로모드 &nbsp; • &nbsp; v1.0.0 VISUAL REWORK</div></div><div class=\"menu-characters\"><div class=\"spark\">✦</div><img class=\"character cat\" src=\"data:image/webp;base64,\" alt=\"뒤돌아선 기묘\"><img class=\"character croc\" src=\"data:image/webp;base64,\" alt=\"뒤돌아선 크다 부장\"></div></section>\n<section class=\"screen intro hidden\" id=\"intro\"><img class=\"comic-cover\" src=\"data:image/webp;base64,\" alt=\"기묘가 CBZP에 출근하고, 이상한 사무실에서 화분을 피하고 크다 부장에게 쫓기는 4컷 만화\"><div class=\"intro-side\"><div class=\"paper\"><span class=\"eyebrow\">EP.01 / FIRST DAY</span><h2>이상한 회사의<br>인턴 생활</h2><p>정말... 이 회사에서<br>살아남을 수 있을까?</p></div><button class=\"cta\" id=\"begin\">사무실로 입장 ▶</button><small>조이스틱: 이동<br>화분: 공격 · 파티션: 벽 넘기<br>PC: 방향키 / WASD · Space · Shift</small></div></section>\n<section class=\"screen play hidden\" id=\"gamePanel\"><canvas id=\"board\" aria-label=\"기묘와 크다 부장이 화분을 던지고 피하는 사무실 게임\"></canvas><div class=\"hudbar\"><div class=\"hud-panel cat\"><img class=\"hud-img\" src=\"data:image/webp;base64,\" alt=\"\"><div><span class=\"hud-name\">기묘 / PLAYER</span><span class=\"hud-value\">🪴 <span id=\"catAmmo\">1</span> · 벽 <span id=\"stackLabel\">1</span>/3</span></div></div><div class=\"hud-center\"><div>POT BREAKER <b style=\"color:#6588d4\">RE</b></div><button class=\"hud-pause\" id=\"pause\" aria-label=\"일시정지\">Ⅱ</button></div><div class=\"hud-panel croc\"><img class=\"hud-img\" src=\"data:image/webp;base64,\" alt=\"\"><div><span class=\"hud-name\">크다 부장 / NPC</span><span class=\"hud-value\">🪴 <span id=\"bossAmmo\">2</span> · <span id=\"bossWall\">READY</span></span></div></div></div><div class=\"status-pill hidden\" id=\"notice\"></div><div class=\"bell hidden\" id=\"bell\">딸랑딸랑</div><div class=\"touch-layer\"><div id=\"joystick\" class=\"joystick\" role=\"group\" aria-label=\"기묘 이동 조이스틱\"><div id=\"knob\" class=\"knob\"></div></div><div class=\"actions\"><button class=\"action jump\" id=\"jump\" aria-label=\"벽 넘기\"><span class=\"symbol\">▦</span>벽 넘기</button><button class=\"action fire\" id=\"fire\" aria-label=\"화분 던지기\"><span class=\"symbol\">🪴</span>던지기</button></div></div><div class=\"legend\">크다의 시야를 피하고 화분을 모아 반격하세요!</div></section>\n<section class=\"screen end hidden\" id=\"end\"><img class=\"ending-art\" id=\"endingArt\" src=\"data:image/webp;base64,\" alt=\"승패 결과 일러스트\"><div class=\"end-panel\"><span class=\"tag\" id=\"endTag\">GAME OVER</span><h2 id=\"endTitle\">기묘 승리!</h2><p id=\"endText\">화분 한 방으로 역전 성공!</p><div class=\"end-btns\"><button class=\"cta\" id=\"again\">↻ 다시 도전</button><button class=\"cta secondary\" id=\"home\">처음으로</button></div></div></section>\n<section class=\"loader hidden\" id=\"loader\"><div class=\"loader-card\"><div class=\"loading-spin\"></div><strong>사무실 문을 열고 있습니다</strong><p>Python 게임 엔진을 준비하고 있습니다.</p><p id=\"loadStatus\"></p><button class=\"cta secondary hidden\" id=\"retry\">다시 시도하기</button></div></section>\n<section class=\"pause-overlay hidden\" id=\"pausePanel\"><div class=\"pause-card\"><h2>잠깐 휴식!</h2><button class=\"cta\" id=\"resume\">계속하기</button><button class=\"cta secondary\" id=\"pauseHome\">처음으로</button></div></section>\n<div class=\"rotate\">📱 스마트폰을 가로로 돌려주세요.<br>가로 화면에 맞춰 제작한 게임입니다.</div>\n</main></div><script src=\"https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js\" defer></script><script defer>window.POT_ASSETS={\"gimyo\":\"data:image/webp;base64,\",\"keuda\":\"data:image/webp;base64,\",\"opening\":\"data:image/webp;base64,\",\"victory\":\"data:image/webp;base64,\",\"defeat\":\"data:image/webp;base64,\",\"concept\":\"data:image/webp;base64,\"};\n(()=>{'use strict';\nconst $=id=>document.getElementById(id),canvas=$('board'),ctx=canvas.getContext('2d');\nconst W=19,H=11,dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};\nlet runtime=null,game=null,active=false,paused=false,raf=0,last=0,acc=0,world=null,keys=new Set(),stick=[0,0],aim=null,jump=false,fire=false,tick=0,animations=new Map(),prevPlayer=null,prevBoss=null;\nconst images={};for(const n of ['gimyo','keuda']){let im=new Image();im.src=window.POT_ASSETS[n];images[n]=im}\nconst show=id=>['title','intro','gamePanel','end'].forEach(n=>$(n).classList.toggle('hidden',n!==id));\n$('openIntro').onclick=()=>show('intro');$('begin').onclick=start;$('again').onclick=start;$('home').onclick=()=>{stop();show('title')};$('pauseHome').onclick=()=>{stop();$('pausePanel').classList.add('hidden');show('title')};$('pause').onclick=()=>{paused=true;$('pausePanel').classList.remove('hidden')};$('resume').onclick=()=>{paused=false;$('pausePanel').classList.add('hidden');last=performance.now()};$('retry').onclick=()=>{ $('loader').classList.add('hidden');start()};\n$('jump').addEventListener('pointerdown',e=>{e.preventDefault();jump=true});$('fire').addEventListener('pointerdown',e=>{e.preventDefault();fire=true});\nwindow.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='Space')fire=true;if(e.code.startsWith('Shift'))jump=true;if(e.code==='Escape'&&active)$('pause').click()});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();stick=[0,0]});\n// Analog-looking stick, discrete grid movement for deterministic Python logic.\nconst joy=$('joystick'),knob=$('knob');let stickId=null;function moveStick(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let x=e.clientX-cx,y=e.clientY-cy,dist=Math.hypot(x,y),radius=r.width*.28;if(dist>radius){x=x/dist*radius;y=y/dist*radius}knob.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`;stick=dist>radius*.28?[x/radius,y/radius]:[0,0]}\njoy.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;joy.setPointerCapture(stickId);moveStick(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function release(e){if(e.pointerId!==stickId)return;stickId=null;stick=[0,0];knob.style.transform='translate(-50%,-50%)'}for(const event of ['pointerup','pointercancel','lostpointercapture'])joy.addEventListener(event,release);\ncanvas.addEventListener('pointerdown',e=>{if(!world)return;const r=canvas.getBoundingClientRect();aim=[(e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H];fire=true});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){const r=canvas.getBoundingClientRect();aim=[(e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H]}});\nfunction stop(){active=false;paused=false;cancelAnimationFrame(raf);keys.clear();stick=[0,0]}\nasync function load(){if(game)return;$('loader').classList.remove('hidden');$('retry').classList.add('hidden');$('loadStatus').textContent='첫 실행에는 Python WebAssembly를 내려받습니다.';try{\n if(!window.loadPyodide)throw new Error('Pyodide 스크립트를 불러오지 못했습니다. 인터넷 연결을 확인해 주세요.');\n runtime=await window.loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v0.27.7/full/'});\n const r=await fetch('game.py',{cache:'no-store'});if(!r.ok)throw new Error('게임 엔진 파일을 찾지 못했습니다.');\n runtime.runPython((await r.text())+'\\ngame = PotBreaker()');game=runtime.globals.get('game');\n }catch(e){$('loadStatus').textContent=String(e);$('retry').classList.remove('hidden');throw e}finally{if(game)$('loader').classList.add('hidden')}}\nasync function start(){stop();try{await load()}catch(e){return}try{world=JSON.parse(game.reset());prevPlayer=null;prevBoss=null;aim=null;acc=0;active=true;show('gamePanel');last=performance.now();updateHUD(world);draw(world);raf=requestAnimationFrame(loop)}catch(e){$('loader').classList.remove('hidden');$('loadStatus').textContent=String(e);$('retry').classList.remove('hidden')}}\nfunction getMove(){for(const [k,d] of [['ArrowUp',[0,-1]],['KeyW',[0,-1]],['ArrowDown',[0,1]],['KeyS',[0,1]],['ArrowLeft',[-1,0]],['KeyA',[-1,0]],['ArrowRight',[1,0]],['KeyD',[1,0]]])if(keys.has(k))return d;const [x,y]=stick;return Math.max(Math.abs(x),Math.abs(y))<.23?[0,0]:Math.abs(x)>Math.abs(y)?[Math.sign(x),0]:[0,Math.sign(y)]}\nfunction updateHUD(s){$('catAmmo').textContent=s.ammo;$('bossAmmo').textContent=s.boss_ammo;$('stackLabel').textContent=s.stacks;$('bossWall').textContent=s.boss_cd>0?`${Math.ceil(s.boss_cd)}s`:'READY';$('jump').disabled=s.stacks<1;$('fire').disabled=s.ammo<1;$('notice').textContent=s.notice;$('notice').classList.toggle('hidden',!s.notice);$('bell').classList.toggle('hidden',!s.bell)}\nfunction loop(now){if(!active)return;if(!paused){let dt=Math.min(.12,(now-last)/1000||.03);tick+=dt;acc+=dt;let count=0;while(acc>=.04&&count++<3){const [mx,my]=getMove();const ax=aim?aim[0]-world.player[0]:0,ay=aim?aim[1]-world.player[1]:0;const fireNow=fire,jumpNow=jump;fire=false;jump=false;const previous=world;world=JSON.parse(game.step(.04,mx,my,jumpNow,fireNow,ax,ay));if(previous&&world){if(previous.player.join()!=world.player.join())animations.set('player',{from:previous.player,to:world.player,start:tick});if(previous.boss.join()!=world.boss.join())animations.set('boss',{from:previous.boss,to:world.boss,start:tick})}acc-=.04;updateHUD(world);if(world.phase!=='playing')break}draw(world);if(world.phase!=='playing'){active=false;window.setTimeout(()=>end(world.phase),450);return}}last=now;raf=requestAnimationFrame(loop)}\nfunction end(outcome){show('end');let win=outcome==='win';$('endingArt').src=window.POT_ASSETS[win?'victory':'defeat'];$('endTag').textContent=win?'★ WINNER ★':'GAME OVER';$('endTitle').textContent=win?'기묘 승리!':'크다 부장 승리!';$('endText').textContent=win?'화분 한 방! 크다 부장의 뚝배기를 깼습니다.':'기묘가 화분에 머리만 내놓고 심어졌습니다…'}\nfunction rr(x,y,w,h,r,c,stroke,sw){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(c){ctx.fillStyle=c;ctx.fill()}if(stroke){ctx.lineWidth=sw||.025;ctx.strokeStyle=stroke;ctx.stroke()}}\nfunction ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}\nfunction strokeLine(pts,c='#8593b1',width=.035){ctx.beginPath();ctx.moveTo(...pts[0]);for(const p of pts.slice(1))ctx.lineTo(...p);ctx.lineWidth=width;ctx.strokeStyle=c;ctx.stroke()}\nfunction plant(x,y,size=1,glow=false){ctx.save();ctx.translate(x,y);ctx.scale(size,size);ellipse(.01,.26,.31,.12,'#66788739');ellipse(0,-.04,.25,.12,'#385d37');for(const [ox,oy,r] of [[-.13,-.23,-.7],[.12,-.28,.4],[0,-.35,0],[-.16,-.05,-1],[.16,-.13,.8]]){ctx.save();ctx.translate(ox,oy);ctx.rotate(r);ellipse(0,0,.12,.19,'#769e55');ellipse(-.025,-.03,.05,.11,'#a6cc75');ctx.restore()}ctx.beginPath();ctx.moveTo(-.26,-.08);ctx.lineTo(.26,-.08);ctx.lineTo(.19,.33);ctx.quadraticCurveTo(0,.39,-.19,.33);ctx.closePath();ctx.fillStyle='#d08b57';ctx.fill();ctx.strokeStyle='#9d654e';ctx.lineWidth=.045;ctx.stroke();rr(-.29,-.12,.58,.105,.04,'#e6a66d','#ae7654',.037);strokeLine([[-.07,.03],[-.055,.22]],'#f4c28c',.04);if(glow){ctx.strokeStyle='#fff1b7';ctx.lineWidth=.052;ctx.beginPath();ctx.arc(0,-.02,.48,0,Math.PI*2);ctx.stroke();for(let i=0;i<4;i++){const a=tick*1.6+i*Math.PI/2;ellipse(Math.cos(a)*.44,Math.sin(a)*.39-.03,.055,.055,'#fff6b7')}}ctx.restore()}\nfunction monitor(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);rr(-.34,-.32,.66,.43,.04,'#3f506d','#657493',.032);rr(-.28,-.27,.54,.33,.02,'#9dcdf1');rr(-.24,-.22,.18,.035,.008,'#e7f8ff');rr(-.24,-.14,.37,.027,.008,'#d7ecff');strokeLine([[0,.11],[0,.27]],'#64738d',.06);rr(-.2,.23,.4,.05,.017,'#63718a');ctx.restore()}\nfunction desk(x,y,variant=0){ctx.save();ctx.translate(x,y);ellipse(.04,.36,.48,.15,'#55637d29');rr(-.47,-.37,.93,.65,.09,'#b3a6a1');rr(-.49,-.43,.94,.63,.09,'#d6c0aa','#b4a89f',.026);rr(-.46,-.41,.88,.54,.06,'#f4e4cd');monitor(-.04,-.08,.85);if(variant%3===0){rr(.16,.12,.25,.18,.016,'#fffdfa','#c7bab3',.013);strokeLine([[.20,.16],[.34,.16]],'#a9c3ce',.018)}else{rr(.21,.12,.19,.13,.02,'#fbfbf5');strokeLine([[.24,.16],[.34,.16]],'#c7c3b7',.018)}ctx.restore()}\nfunction wall(x,y,kind){ctx.save();ctx.translate(x,y);ellipse(.52,.83,.5,.13,'#56698524');rr(.09,.11,.87,.78,.06,'#748baf');rr(.045,.045,.91,.77,.05,'#c8d6e4','#8398b4',.03);rr(.075,.065,.84,.11,.025,'#f1f7ff');rr(.10,.21,.79,.41,.04,'#e8f2fc','#a6b5cc',.02);strokeLine([[.15,.20],[.15,.62]],'#c4d2e1',.016);rr(.07,.66,.87,.11,.02,'#9ab0cf');if(kind%4===0){rr(.46,.33,.25,.29,.01,'#fff4d4','#e2cfa4',.018);strokeLine([[.48,.38],[.64,.38]],'#cfb982',.016)}ctx.restore()}\nfunction floor(){const grad=ctx.createLinearGradient(0,0,W,H);grad.addColorStop(0,'#fff4e9');grad.addColorStop(.55,'#eee8e2');grad.addColorStop(1,'#e1eaf4');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);for(let y=0;y<H;y++)for(let x=0;x<W;x++){ctx.fillStyle=(x+y)%3===0?'#ffffff0c':'#87a9c30a';ctx.fillRect(x,y,1,1);ctx.strokeStyle='#afbed052';ctx.lineWidth=.015;ctx.strokeRect(x,y,1,1)}ctx.save();const g=ctx.createLinearGradient(-3,0,13,10);g.addColorStop(0,'#ffffff90');g.addColorStop(.53,'#ffffff10');g.addColorStop(1,'#ffffff02');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(7,0);ctx.lineTo(16,11);ctx.lineTo(7,11);ctx.closePath();ctx.fill();ctx.restore()}\nfunction vision(s){let x=s.boss[0]+.5,y=s.boss[1]+.5,angle=Math.atan2(s.boss_face[1],s.boss_face[0]);for(const off of [[5,155],[-155,-5]]){const a=angle+off[0]*Math.PI/180,b=angle+off[1]*Math.PI/180;ctx.beginPath();ctx.moveTo(x,y);ctx.arc(x,y,s.vision_radius,a,b,false);ctx.closePath();ctx.fillStyle='#fa928a30';ctx.fill();ctx.strokeStyle='#f1a29b66';ctx.lineWidth=.025;ctx.stroke()}}\nfunction actor(asset,coords,role){const ani=animations.get(role);let [x,y]=coords;if(ani){const d=Math.min(1,(tick-ani.start)/.115);if(d<1){x=ani.from[0]+(ani.to[0]-ani.from[0])*d;y=ani.from[1]+(ani.to[1]-ani.from[1])*d}else animations.delete(role)}const bob=Math.sin(tick*(role==='player'?14:6))*.025;ctx.save();ctx.translate(x+.5,y+.5);ellipse(0,.39,role==='player'?.6:.67,.18,'#525b7a38');const im=images[asset];let w=role==='player'?1.85:2.16,h=role==='player'?1.72:1.94;if(im.complete&&im.naturalWidth){ctx.save();ctx.filter='drop-shadow(0px 0.05px 0.05px #59688145)';ctx.drawImage(im,-w/2,-h*.76+bob,w,h);ctx.restore()}else{ellipse(0,-.2,.45,.55,role==='player'?'#9b9088':'#9bba73')}ctx.restore()}\nfunction bubbles(s){if(s.bell){ctx.save();ctx.fillStyle='#fff9e8c9';rr(8.3,9.25,2.35,.48,.25,'#fff6decc','#e6c58f',.026);ctx.font='bold .29px sans-serif';ctx.fillStyle='#bc8a4f';ctx.textAlign='center';ctx.fillText('딸랑딸랑',9.47,9.58);ctx.restore()}}\nfunction draw(s){const dpr=Math.min(2,devicePixelRatio||1),box=canvas.getBoundingClientRect();if(!box.width||!box.height)return;const rw=Math.floor(box.width*dpr),rh=Math.floor(box.height*dpr);if(canvas.width!==rw||canvas.height!==rh){canvas.width=rw;canvas.height=rh}ctx.setTransform(rw/W,0,0,rh/H,0,0);ctx.clearRect(0,0,W,H);floor();\nconst obstacles=new Set(s.walls.map(p=>p.join(',')));for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(obstacles.has(x+','+y))wall(x,y,x*7+y*3);else if((x*13+y*19)%29===1 && (Math.abs(x-s.player[0])+Math.abs(y-s.player[1])>2))desk(x+.5,y+.42,x+y);else if((x*7+y*11)%47===9){ctx.save();ctx.globalAlpha=.55;plant(x+.5,y+.5,.43);ctx.restore()}}vision(s);\nfor(const p of s.pots)plant(p[0]+.5,p[1]+.42,.83,true);\nactor('keuda',s.boss,'boss');actor('gimyo',s.player,'player');for(const p of s.projectiles){plant(p.x+.5,p.y+.26,p.boss?.72:.52,true)}bubbles(s);\n}\n// Debug-only manual visual check: local tests can set a state without loading Pyodide.\nwindow.__potBreakerVisualCheck=(state)=>{world=state;show('gamePanel');draw(state)};\n})();\n</script>\n</body></html>";
const GAME="import random, math, json\n\nWIDTH, HEIGHT = 19, 11\n\n\ndef distance(a, b):\n    return math.hypot(a[0] - b[0], a[1] - b[1])\n\n\nclass PotBreaker:\n    \"\"\"Single-player office maze rules; deterministic JSON state for Canvas UI.\"\"\"\n\n    def __init__(self, seed=None):\n        self.rng = random.Random(seed)\n        self.reset()\n\n    def reset(self):\n        self.phase = 'playing'\n        self.clock = 0.0\n        self.player = list(self.rng.choice([(1, 1), (1, HEIGHT - 2), (WIDTH - 2, 1), (WIDTH - 2, HEIGHT - 2)]))\n        self.boss = [WIDTH // 2, HEIGHT // 2]\n        self.face = [1, 0]\n        self.boss_face = [1, 0]\n        self.walls = set()\n        safe = {tuple(self.player), tuple(self.boss)}\n        for y in range(1, HEIGHT-1):\n            for x in range(1, WIDTH-1):\n                if (x, y) not in safe and abs(x - self.player[0]) + abs(y - self.player[1]) > 2 and abs(x - self.boss[0]) + abs(y - self.boss[1]) > 2 and self.rng.random() < 0.23:\n                    self.walls.add((x, y))\n        # Carve openings if a random partition layout blocks every route.\n        while self.walls and not self._is_connected(self.player, self.boss):\n            self.walls.remove(self.rng.choice(tuple(self.walls)))\n        self.ammo = 1\n        self.boss_ammo = 2\n        self.jump_stacks = 1.0\n        self.boss_jump_cd = 0.0\n        self.throw_cd = 0.0\n        self.boss_throw_cd = 1.5\n        self.player_move_cd = 0.0\n        self.boss_move_cd = 0.4\n        self.alert = 0.0\n        self.last_seen = None\n        self.bell = 0.0\n        self.notice = '크다 부장의 시야를 피해 이동하세요.'\n        self.notice_time = 2.2\n        self.projectiles = []\n        self.pots = []\n        self.roam = None\n        for _ in range(3):\n            self._add_pot()\n        return self.state()\n\n    def _free(self, x, y):\n        return 0 <= x < WIDTH and 0 <= y < HEIGHT and (x, y) not in self.walls\n\n    def _is_connected(self, start, goal):\n        q, seen = [tuple(start)], {tuple(start)}\n        for x, y in q:\n            if (x, y) == tuple(goal):\n                return True\n            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n                nx, ny = x + dx, y + dy\n                if self._free(nx, ny) and (nx, ny) not in seen:\n                    seen.add((nx, ny))\n                    q.append((nx, ny))\n        return False\n\n    def _add_pot(self):\n        choices = [(x, y) for x in range(WIDTH) for y in range(HEIGHT)\n                   if self._free(x, y) and [x, y] not in (self.player, self.boss) and [x, y] not in self.pots]\n        if choices:\n            self.pots.append(list(self.rng.choice(choices)))\n\n    def _path_step(self, start, goal):\n        start, goal = tuple(start), tuple(goal)\n        if start == goal:\n            return start\n        q = [start]\n        came = {start: None}\n        for p in q:\n            if p == goal:\n                break\n            for dx, dy in self.rng.sample([(0,1),(1,0),(0,-1),(-1,0)], 4):\n                n = (p[0]+dx, p[1]+dy)\n                if self._free(*n) and n not in came:\n                    came[n] = p\n                    q.append(n)\n        if goal not in came:\n            return start\n        p = goal\n        while came[p] not in (None, start):\n            p = came[p]\n        return p\n\n    def _sees_player(self):\n        # Partition walls do NOT obstruct vision; configurable distance is in grid cells.\n        if distance(self.player, self.boss) > 3.4:\n            return False\n        dx, dy = self.player[0] - self.boss[0], self.player[1] - self.boss[1]\n        theta = abs(math.degrees(math.atan2(self.boss_face[0]*dy-self.boss_face[1]*dx,\n                                             self.boss_face[0]*dx+self.boss_face[1]*dy)))\n        return 5 <= theta <= 155\n\n    def _pickups(self):\n        for who, cap, attr in ((self.player, 1, 'ammo'), (self.boss, 2, 'boss_ammo')):\n            if getattr(self, attr) >= cap:\n                continue\n            for pot in list(self.pots):\n                if distance(who, pot) < 0.65:\n                    setattr(self, attr, getattr(self, attr) + 1)\n                    self.pots.remove(pot)\n                    self._add_pot()\n                    break\n\n    def _fire(self, who, vec, boss=False):\n        ammo_field = 'boss_ammo' if boss else 'ammo'\n        if getattr(self, ammo_field) < 1:\n            return\n        length = math.hypot(*vec)\n        if length < 0.001:\n            vec, length = [1, 0], 1\n        setattr(self, ammo_field, getattr(self, ammo_field) - 1)\n        self.projectiles.append({'x':float(who[0]),'y':float(who[1]),\n                                 'dx':vec[0]/length,'dy':vec[1]/length,\n                                 'range':7.3 if boss else 4.2,'boss':boss})\n\n    def _jump_player(self, dx, dy):\n        if self.jump_stacks < 1 or not (dx or dy):\n            return False\n        x, y = self.player\n        if (x+dx,y+dy) not in self.walls or not self._free(x+2*dx,y+2*dy):\n            return False\n        self.player = [x+2*dx,y+2*dy]\n        self.jump_stacks -= 1\n        return True\n\n    def _move_boss(self):\n        visible = self._sees_player()\n        if visible:\n            self.last_seen = list(self.player)\n            self.alert = 2.8\n        target = self.last_seen if self.alert > 0 and self.last_seen else None\n        if not target:\n            if self.roam is None or self.boss == self.roam or self.rng.random() < .10:\n                self.roam = [self.rng.randrange(1,WIDTH-1), self.rng.randrange(1,HEIGHT-1)]\n            target = self.roam\n        dx = 0 if target[0] == self.boss[0] else (1 if target[0] > self.boss[0] else -1)\n        dy = 0 if target[1] == self.boss[1] else (1 if target[1] > self.boss[1] else -1)\n        primary = (dx,0) if abs(target[0]-self.boss[0]) >= abs(target[1]-self.boss[1]) else (0,dy)\n        if primary == (0,0):\n            primary = (dx,dy)\n        if visible and self.boss_jump_cd <= 0 and self.boss_ammo > 0:\n            for d in ([primary,(0,dy),(dx,0)]):\n                if d == (0,0):\n                    continue\n                tx, ty = self.boss\n                count = 0\n                while (tx+d[0],ty+d[1]) in self.walls and count < 3:\n                    tx += d[0]\n                    ty += d[1]\n                    count += 1\n                if count and self._free(tx+d[0],ty+d[1]):\n                    self.boss = [tx+d[0], ty+d[1]]\n                    self.boss_face = list(d)\n                    self.boss_jump_cd = 15.0\n                    self.notice, self.notice_time = '쾅! 크다 부장이 파티션을 뚫었습니다!', 0.9\n                    return\n        nxt = self._path_step(self.boss, target)\n        if nxt != tuple(self.boss):\n            self.boss_face = [nxt[0]-self.boss[0],nxt[1]-self.boss[1]]\n            self.boss = list(nxt)\n        elif not visible:\n            self.roam = None\n\n    def _advance_projectiles(self, dt):\n        for p in list(self.projectiles):\n            p['x'] += p['dx'] * dt * (7.1 if p['boss'] else 9.6)\n            p['y'] += p['dy'] * dt * (7.1 if p['boss'] else 9.6)\n            p['range'] -= dt * (7.1 if p['boss'] else 9.6)\n            if p['range'] <= 0 or not (0 <= p['x'] < WIDTH and 0 <= p['y'] < HEIGHT):\n                self.projectiles.remove(p)\n                continue\n            if not p['boss'] and (round(p['x']),round(p['y'])) in self.walls:\n                self.projectiles.remove(p)\n                continue\n            for other in list(self.projectiles):\n                if other is p or other['boss'] == p['boss']:\n                    continue\n                if math.hypot(p['x']-other['x'],p['y']-other['y']) < .5:\n                    small = p if not p['boss'] else other\n                    if small in self.projectiles:\n                        self.projectiles.remove(small)\n                    break\n            if p not in self.projectiles:\n                continue\n            target = self.player if p['boss'] else self.boss\n            if distance((p['x'],p['y']),target) < .56:\n                self.phase = 'lose' if p['boss'] else 'win'\n                self.projectiles.clear()\n                break\n\n    def step(self, dt, mx=0, my=0, jump=False, fire=False, aimx=0, aimy=0):\n        if self.phase != 'playing':\n            return self.state()\n        dt = min(.085,max(0.01,float(dt)))\n        self.clock += dt\n        self.jump_stacks = min(3.,self.jump_stacks+dt/5.)\n        self.boss_jump_cd = max(0.,self.boss_jump_cd-dt)\n        self.throw_cd = max(0.,self.throw_cd-dt)\n        self.boss_throw_cd = max(0.,self.boss_throw_cd-dt)\n        self.player_move_cd -= dt\n        self.boss_move_cd -= dt\n        self.notice_time = max(0.,self.notice_time-dt)\n        self.bell = max(0.,self.bell-dt)\n        self.alert = max(0.,self.alert-dt)\n        dx, dy = int(mx), int(my)\n        if dx and dy:\n            dy = 0\n        if dx or dy:\n            self.face = [dx,dy]\n        if jump and (dx or dy):\n            if self._jump_player(dx,dy):\n                self.player_move_cd = .10\n        if self.player_move_cd <= 0 and (dx or dy):\n            tx,ty = self.player[0]+dx,self.player[1]+dy\n            if self._free(tx,ty):\n                self.player = [tx,ty]\n            self.player_move_cd = .115\n        if fire and self.throw_cd <= 0 and self.ammo:\n            self._fire(self.player,[float(aimx) if aimx or aimy else self.face[0],\n                                    float(aimy) if aimx or aimy else self.face[1]])\n            self.throw_cd = .40\n        if self.boss_move_cd <= 0:\n            self._move_boss()\n            self.boss_move_cd = .32\n        if self.boss_throw_cd <= 0 and self.boss_ammo and distance(self.player,self.boss) < 7.4 and self._sees_player():\n            self._fire(self.boss,[self.player[0]-self.boss[0],self.player[1]-self.boss[1]],True)\n            self.boss_throw_cd = 2.8\n        if (dx or dy) and distance(self.player,self.boss) <= 5:\n            self.bell = .7\n        self._advance_projectiles(dt)\n        self._pickups()\n        return self.state()\n\n    def state(self):\n        return json.dumps({'phase':self.phase,'player':self.player,'boss':self.boss,\n            'face':self.face,'boss_face':self.boss_face,'walls':list(self.walls),'pots':self.pots,\n            'ammo':self.ammo,'boss_ammo':self.boss_ammo,'stacks':int(self.jump_stacks),\n            'jump_progress':round(self.jump_stacks%1,2),'boss_cd':round(self.boss_jump_cd,1),\n            'bell':self.bell>0,'notice':self.notice if self.notice_time else '',\n            'projectiles':self.projectiles,'vision_radius':3.4},ensure_ascii=False)\n\nif __name__ == '__main__':\n    game=PotBreaker(9)\n    for i in range(2000):\n        s=json.loads(game.step(.04,1 if i%6 < 3 else -1, 0, i%30==0, i%18==0,1,0))\n        assert len(s['pots'])==3 and 0<=s['stacks']<=3\n        if s['phase']!='playing': game.reset()\n    print('OK: 2000 ticks')\n";
export default {async fetch(request){
const path=new URL(request.url).pathname;
if(!["GET","HEAD"].includes(request.method))return new Response("Method Not Allowed",{status:405,headers:{Allow:"GET, HEAD"}});
if(path==="/health")return new Response(JSON.stringify({ok:true,version:"1.0.0",visual:"illustrated",engine:"Python/Pyodide"}),{headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}});
const page=path==="/"||path==="/index.html";
if(!page&&path!=="/game.py")return new Response("Not Found",{status:404});
const headers={"content-type":page?"text/html; charset=utf-8":"text/plain; charset=utf-8","cache-control":"public, max-age=60","x-content-type-options":"nosniff"};
return new Response(request.method==="HEAD"?null:(page?PAGE:GAME),{status:200,headers});
}};